inline I log(I x){const I n=clamp(x)+1,b=std::bit_width(std::uint64_t(n))-1,base=I(1)<<b,pos=((n-base)<<16)/base,i=pos>>8,f=pos&255;return (b<<12)+LogLut[i]+(LogLut[i+1]-LogLut[i])*f/256;}
inline I clip(I x){return std::clamp(x,I(-1000000000),I(1000000000));}
inline I sigmoid(I z){z=std::clamp(z,I(-12000),I(12000));const I n=z+12000,i=std::min(n/50,I(479)),r=n-i*50;return SigLut[i]+(SigLut[i+1]-SigLut[i])*r/50;}
inline I positive_probability(const std::array<I,7>& x){constexpr I c[]={8611978,43228153,15718211,-6516635,-3590905,14197190,17976534};I z=-1669121786493LL;for(int i=0;i<7;++i)z+=x[i]*c[i];return clip(z/(I(1)<<28));}
